func newLabCluster(t *testing.T, size int) *labCluster {
	t.Helper()
	ports := freeClientPorts(t, 2*size)
	cluster := &labCluster{clientPorts: ports[:size], routePorts: ports[size:], stores: make([]string, size),
		runtimes: make([]*Runtime, size), routes: make([]string, size)}
	for index := range size {
		cluster.routes[index] = fmt.Sprintf("nats-route://127.0.0.1:%d", cluster.routePorts[index])
		cluster.stores[index] = filepath.Join(t.TempDir(), fmt.Sprintf("peer%d", index))
	}
	t.Cleanup(func() {
		for _, runtime := range cluster.runtimes {
			_ = runtime.Close()
		}
	})
	return cluster
}

func (cluster *labCluster) start(t *testing.T, ctx context.Context, index int) *Runtime {
	t.Helper()
	instance := fmt.Sprintf("peer%d", index)
	runtime, err := Start(ctx, Config{Cell: "lab", Instance: instance, Replicas: len(cluster.routes), Lab: true,
		Embedded: &Embedded{Host: "127.0.0.1", Port: cluster.clientPorts[index], RouteHost: "127.0.0.1",
			RoutePort: cluster.routePorts[index], Routes: PeerRoutes(cluster.routes, cluster.routes[index]),
			StoreDir: cluster.stores[index], BrokerIDs: []string{"peer0", "peer1", "peer2"}[:len(cluster.routes)]},
	})
	if err != nil {
		t.Fatal(err)
	}
	cluster.runtimes[index] = runtime
	return runtime
}

func (cluster *labCluster) stop(index int) {
	if cluster.runtimes[index] != nil {
		_ = cluster.runtimes[index].Close()
		cluster.runtimes[index] = nil
	}
}

func waitUntil(t *testing.T, ctx context.Context, what string, ready func() bool) {
	t.Helper()
	for !ready() {
		if err := ctx.Err(); err != nil {
			t.Fatalf("%s: %v", what, err)
		}
		time.Sleep(50 * time.Millisecond)
	}
}

func createR3Stream(ctx context.Context, js jetstream.JetStream) (jetstream.Stream, error) {
	var stream jetstream.Stream
	var err error
	for ctx.Err() == nil {
		attempt, cancel := context.WithTimeout(ctx, 5*time.Second)
		stream, err = js.CreateOrUpdateStream(attempt, jetstream.StreamConfig{Name: "FORMATION",
			Subjects: []string{"formation.>"}, Replicas: 3, Storage: jetstream.FileStorage})
		cancel()
		if err == nil {
			return stream, nil
		}
		time.Sleep(100 * time.Millisecond)
	}
	return nil, fmt.Errorf("create R3 stream: %w", err)
}

internal/natscell/host_reconnect_test.go.source:
func freeClientPort(t *testing.T) int {
	t.Helper()
	return freeClientPorts(t, 1)[0]
}

func freeClientPorts(t *testing.T, count int) []int {
	t.Helper()
	var listeners []net.Listener
	defer func() {
		for _, listener := range listeners {
			if err := listener.Close(); err != nil {
				t.Error(err)
			}
		}
	}()
	ports := make([]int, count)
	for index := range count {
		listener, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatal(err)
		}
		listeners = append(listeners, listener)
		ports[index] = listener.Addr().(*net.TCPAddr).Port
	}
	return ports
}

internal/natscell/health.go::ObserveClus.source:
func (r *Runtime) ObserveCluster() (ClusterObservation, error) {
	if r == nil || r.server == nil {
		return ClusterObservation{}, errors.New("cluster observation requires an embedded regional NATS server")
	}
	observation := ClusterObservation{ServerName: r.serverName, Running: r.server.Running(),
		ExpectedPeers: slices.Clone(r.brokerNames)}
	if !observation.Running {
		return observation, nil
	}
	if routes, err := r.server.Routez(nil); err == nil {
		for _, route := range routes.Routes {
			if route != nil && route.RemoteName != "" && !slices.Contains(observation.Routes, route.RemoteName) {
				observation.Routes = append(observation.Routes, route.RemoteName)
			}
		}
		slices.Sort(observation.Routes)
	}
	info, err := r.server.Jsz(nil)
	if err != nil {
		return observation, err
	}
	if info.Disabled {
		// JetStream was never enabled or was shut down after a store
		// failure, which also clears JetStreamIsClustered while the NATS
		// server keeps running. Never present that as a healthy group.
		return observation, ErrJetStreamDisabled
	}
	if info.Meta == nil {
		if !r.server.JetStreamIsClustered() && len(r.brokerNames) <= 1 {
			// A standalone broker is its own single-member metadata group.
			observation.MetaLeader, observation.MetaSize, observation.MetaQuorum = r.serverName, 1, 1
		}
		return observation, nil
	}
	observation.MetaLeader = info.Meta.Leader
	observation.MetaSize = info.Meta.Size
	observation.MetaQuorum = info.Meta.QuorumNeeded
	observation.MetaPeers = metaReplicas(info.Meta.Replicas)
	return observation, nil
}

internal/natscell/health.go::PeerRoutes.source:
func PeerRoutes(routes []string, self string) []string {
	peers := make([]string, 0, len(routes))
	for _, route := range routes {
		if route != self {
			peers = append(peers, route)
		}
	}
	return peers
}

internal/natscell/shutdown.go::drainConn.source:
func drainConnection(conn *nats.Conn, timeout time.Duration) {
	if conn.IsClosed() {
		return
	}
	if err := conn.Drain(); err == nil {
		deadline := time.Now().Add(timeout)
		for !conn.IsClosed() && time.Now().Before(deadline) {
			time.Sleep(10 * time.Millisecond)
		}
	}
	conn.Close()
}

internal/natscell/shutdown.go::stopServe.source:
func (r *Runtime) stopServer() {
	if r.server.Running() && r.server.JetStreamIsClustered() {
		r.handOffLeadership(closeHandoffTimeout)
		// Lame-duck mode transfers every remaining Raft leadership, including
		// the metadata leader, and waits for the transfer before stopping
		// JetStream. NATS skips it when the server has no client listener
		// (production DontListen); Shutdown below still steps every Raft
		// leader down first, only without waiting for the transfer.
		r.server.LameDuckShutdown()
	}
	r.server.Shutdown()
	r.server.WaitForShutdown()
}

internal/natscell/shutdown.go::handOffLe.source:
func (r *Runtime) handOffLeadership(timeout time.Duration) {
	led := r.ledGroups()
	if len(led) == 0 {
		return
	}
	for _, group := range led {
		if group.consumer == "" {
			_ = r.server.JetStreamStepdownStream(group.account, group.stream)
		} else {
			_ = r.server.JetStreamStepdownConsumer(group.account, group.stream, group.consumer)
		}
	}
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) && !successorsElected(r.groupLeaders(), led, r.server.Name()) {
		time.Sleep(50 * time.Millisecond)
	}
}

internal/natscell/shutdown.go::successor.source:
func successorsElected(leaders map[ledGroup]string, led []ledGroup, self string) bool {
	if leaders == nil {
		return false
	}
	for _, group := range led {
		if leader, ok := leaders[group]; ok && (leader == "" || leader == self) {
			return false
		}
	}
	return true
}

internal/natscell/shutdown.go::groupLead.source:
func (r *Runtime) groupLeaders() map[ledGroup]string {
	info, err := r.server.Jsz(&server.JSzOptions{Accounts: true, Streams: true, Consumer: true})
	if err != nil || info == nil {
		return nil
	}
	leaders := map[ledGroup]string{}
	for _, account := range info.AccountDetails {
		if account == nil {
			continue
		}
		for _, stream := range account.Streams {
			if stream.Cluster != nil {
				leaders[ledGroup{account: account.Id, stream: stream.Name}] = stream.Cluster.Leader
			}
			for _, consumer := range stream.Consumer {
				if consumer != nil && consumer.Cluster != nil {
					leaders[ledGroup{account: account.Id, stream: stream.Name, consumer: consumer.Name}] =
						consumer.Cluster.Leader
				}
			}
		}
	}
	return leaders
}

internal/natscell/shutdown.go::ledGroups.source:
func (r *Runtime) ledGroups() []ledGroup {
	info, err := r.server.Jsz(&server.JSzOptions{Accounts: true, Streams: true, Consumer: true})
	if err != nil || info == nil {
		return nil
	}
	name := r.server.Name()
	var led []ledGroup
	for _, account := range info.AccountDetails {
		if account == nil {
			continue
		}
		for _, stream := range account.Streams {
			if stream.Cluster != nil && stream.Cluster.Leader == name && hasCurrentPeer(stream.Cluster.Replicas) {
				led = append(led, ledGroup{account: account.Id, stream: stream.Name})
			}
			for _, consumer := range stream.Consumer {
				if consumer != nil && consumer.Cluster != nil && consumer.Cluster.Leader == name &&
					hasCurrentPeer(consumer.Cluster.Replicas) {
					led = append(led, ledGroup{account: account.Id, stream: stream.Name, consumer: consumer.Name})
				}
			}
		}
	}
	return led
}

internal/natscell/shutdown.go::hasCurren.source:
func hasCurrentPeer(peers []*server.PeerInfo) bool {
	for _, peer := range peers {
		if peer != nil && peer.Current && !peer.Offline {
			return true
		}
	}
	return false
}

internal/natscell/runtime.go::userPermis.source:
func userPermissions(cell string, user NKeyGrant) (*server.Permissions, error) {
	inbox := inboxPrefix(cell, user.PublicKey) + ".>"
	permissions := &server.Permissions{Subscribe: &server.SubjectPermission{Allow: []string{inbox}}}
	if user.Global && user.Role != "controller" {
		return nil, errors.New("only a controller NATS user may carry global home grants")
	}
	switch user.Role {
	case "host":
		if !cellName.MatchString(user.Node) {
			return nil, errors.New("host NATS user needs a valid node identity")
		}
		permissions.Publish = &server.SubjectPermission{Allow: []string{
			protocol.AgentObservation(cell, user.PublicKey, "*"),
		}}
	case "controller":
		if user.Node != "" {
			return nil, errors.New("controller NATS user must not carry a host node")
		}
		permissions.Publish = &server.SubjectPermission{Allow: []string{
			protocol.Regional(cell, ">"), protocol.Control(cell, ">"), "$JS.API.>", "$KV.>", "$O.>",
			"$JS.ACK.TS_DELIVERY_INTENTS.TS_DELIVERY_WORKER.>",
		}}
		for _, leaf := range protocol.InterRegionObservabilityLeaves() {
			permissions.Publish.Allow = append(permissions.Publish.Allow, protocol.AnyRegionObservabilitySubject(leaf))
		}
		permissions.Publish.Allow = append(permissions.Publish.Allow, protocol.AnyRegionQuerySubject())
		if user.Global {
			permissions.Publish.Allow = append(permissions.Publish.Allow, GlobalControllerPublishes()...)
			permissions.Publish.Allow = append(permissions.Publish.Allow, GlobalControllerRequests()...)
			permissions.Subscribe.Allow = append(permissions.Subscribe.Allow, GlobalControllerRequests()...)
		}
		permissions.Subscribe.Allow = append(permissions.Subscribe.Allow,
			ControllerSubscriptions(cell)...)
		// Read-only member telemetry: every controller answers observability
		// snapshot requests for its cell.
		permissions.Subscribe.Allow = append(permissions.Subscribe.Allow, protocol.ObservabilityGrant(cell))
	case "operator":
		if user.Node != "" {
			return nil, errors.New("operator NATS user must not carry a host node")
		}
		permissions.Publish = &server.SubjectPermission{Allow: []string(BrokerOperatorPublishPermissions(cell))}
	default:
		return nil, fmt.Errorf("invalid NATS user role %q", user.Role)
	}
	return permissions, nil
}

