func (p *tcpProxy) forward(dst, src net.Conn) {
	_, _ = io.Copy(proxyWriter{p, dst}, src)
	if !p.silent.Load() {
		_ = dst.Close()
	}
}

internal/natscell/interregion_test.go::W.source:
func (p proxyWriter) Write(b []byte) (int, error) {
	if p.proxy.silent.Load() {
		return len(b), nil
	}
	return p.w.Write(b)
}

internal/natscell/interregion_test.go::C.source:
func (p *tcpProxy) Close() {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.listener != nil {
		_ = p.listener.Close()
		p.listener = nil
	}
	for _, conn := range p.conns {
		_ = conn.Close()
	}
	p.conns = nil
}

