func (r *Reader) Document(ctx context.Context, kind Kind, cell string) (Document, error) {
	if !validDocument(kind, cell) {
		return Document{}, errDocumentKey
	}
	stored, sequence, err := r.read(ctx, kind, cell)
	if err != nil {
		return Document{}, err
	}
	if len(stored.Payload) == 0 || len(stored.Payload) > maxRecordBytes {
		return Document{}, ErrRecordCorrupt
	}
	return Document{Payload: stored.Payload, Generation: stored.Generation, Epoch: stored.Epoch, Sequence: sequence}, nil
}

internal/globalcontrol/document.go::Foll.source:
func (r *Reader) Follow(ctx context.Context, kind Kind, cell string, recheck time.Duration,
	apply func(context.Context, Document),
) error {
	if !validDocument(kind, cell) {
		return errDocumentKey
	}
	if recheck <= 0 {
		return errors.New("global document recheck must be positive")
	}
	changed := make(chan struct{}, 1)
	var watch jetstream.ConsumeContext
	defer func() {
		if watch != nil {
			watch.Stop()
		}
	}()
	ticker := time.NewTicker(recheck)
	defer ticker.Stop()
	var failure string
	for {
		var watchErr error
		if watch == nil {
			watch, watchErr = r.watch(ctx, subject(kind, cell), changed)
		}
		document, err := r.Document(ctx, kind, cell)
		switch {
		case err == nil:
			apply(ctx, document)
		case errors.Is(err, ErrNotFound):
			err = nil
		}
		if err = errors.Join(watchErr, err); err != nil && err.Error() != failure && ctx.Err() == nil {
			slog.WarnContext(ctx, "global document unavailable", observability.ComponentKey, "globalcontrol",
				"kind", kind, "cell", cell, "error", err)
		}
		failure = ""
		if err != nil {
			failure = err.Error()
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-changed:
		case <-ticker.C:
		}
	}
}

internal/globalcontrol/document.go::watc.source:
func (r *Reader) watch(ctx context.Context, subject string, changed chan<- struct{}) (jetstream.ConsumeContext, error) {
	if r == nil || r.stream == nil {
		return nil, errors.New("global control reader is not open")
	}
	createCtx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()
	consumer, err := r.stream.OrderedConsumer(createCtx, jetstream.OrderedConsumerConfig{
		FilterSubjects: []string{subject}, DeliverPolicy: jetstream.DeliverLastPerSubjectPolicy,
	})
	if err != nil {
		return nil, err
	}
	return consumer.Consume(func(jetstream.Msg) {
		select {
		case changed <- struct{}{}:
		default:
		}
	})
}

internal/globalcontrol/store.go::OpenHom.source:
func OpenHome(ctx context.Context, js jetstream.JetStream, cell string, peers []string, replicas int,
	fencer authority.Fencer,
) (*Writer, error) {
	if !cellToken.MatchString(cell) {
		return nil, errors.New("global home cell is invalid")
	}
	if err := validMirrorPeers(cell, peers); err != nil {
		return nil, err
	}
	if fencer == nil || fencer.Current().Scope != protocol.GlobalScope {
		return nil, errors.New("global writes require the global-scope authority")
	}
	stream, err := openStream(ctx, js, HomeStreamConfig(replicas), func(actual jetstream.StreamConfig) error {
		return verifyHome(actual, replicas)
	})
	if err != nil {
		return nil, err
	}
	if err := ensureMirrorConsumers(ctx, stream, peers, replicas); err != nil {
		return nil, err
	}
	if err := removeStaleMirrorConsumers(ctx, stream, peers); err != nil {
		return nil, err
	}
	return &Writer{Reader: Reader{stream: stream, js: js}, home: cell, fencer: fencer, replicas: replicas}, nil
}

internal/globalcontrol/store.go::read.source:
func (r *Reader) read(ctx context.Context, kind Kind, key string) (record, uint64, error) {
	if r == nil || r.stream == nil {
		return record{}, 0, errors.New("global control reader is not open")
	}
	readCtx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()
	message, err := r.stream.GetLastMsgForSubject(readCtx, subject(kind, key))
	if r.mirror && (err == nil || errors.Is(err, jetstream.ErrMsgNotFound)) {
		// Checked after the read: no gap up to the mirror's last sequence
		// now means no newer record for this subject was skipped before it.
		if gapErr := r.checkMirrorGapFree(readCtx); gapErr != nil {
			return record{}, 0, gapErr
		}
	}
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return record{}, 0, ErrNotFound
	}
	if err != nil {
		return record{}, 0, err
	}
	var stored record
	if err := protocol.DecodeStrict(message.Data, &stored, maxMessageBytes); err != nil ||
		stored.Version != recordVersion || stored.Kind != kind || stored.Key != key ||
		stored.Generation == 0 || stored.Epoch == 0 {
		return record{}, 0, ErrRecordCorrupt
	}
	if !epochHeaderMatches(message.Header, stored.Epoch) {
		return record{}, 0, ErrRecordCorrupt
	}
	return stored, message.Sequence, nil
}

internal/globalcontrol/store.go::checkMi.source:
func (r *Reader) checkMirrorGapFree(ctx context.Context) error {
	info, err := r.info(ctx)
	if err != nil {
		return fmt.Errorf("inspect global mirror: %w", err)
	}
	state := info.State
	if state.LastSeq == 0 {
		// An empty mirror proves nothing until it has heard from the home
		// stream and has nothing left to copy: before its first contact
		// (initial catch-up, or a home that never created this region's
		// mirror consumer) "not found" would be a guess.
		if mirror := info.Mirror; mirror == nil || mirror.Active < 0 || mirror.Lag != 0 {
			return ErrMirrorNotCaughtUp
		}
		return nil
	}
	if state.NumDeleted != 0 || state.FirstSeq != 1 || state.Msgs != state.LastSeq {
		return ErrMirrorGap
	}
	return nil
}

