internal/globalcontrol/store.go::put.source:
func (w *Writer) put(ctx context.Context, epoch uint64, kind Kind, key string, generation uint64, payload []byte,
	admit func(prior []byte) error,
) (uint64, error) {
	if epoch == 0 {
		return 0, authority.ErrFenced
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	if err := w.fencer.Guard(ctx, epoch); err != nil {
		return 0, err
	}
	for range maxAppendAttempts {
		lastSequence, err := w.establishTerm(ctx, epoch)
		if err != nil {
			return 0, err
		}
		next := max(generation, 1)
		prior, priorSequence, err := w.read(ctx, kind, key)
		switch {
		case errors.Is(err, ErrNotFound):
		case err != nil:
			return 0, err
		case priorSequence > lastSequence:
			continue
		case (generation == 0 || prior.Generation == generation) && bytes.Equal(prior.Payload, payload):
			// An identical retry after an unknown publish outcome is idempotent.
			return priorSequence, nil
		case generation == 0:
			next = prior.Generation + 1
		case generation <= prior.Generation:
			return 0, ErrStaleRecord
		}
		if epoch < prior.Epoch {
			return 0, authority.ErrFenced
		}
		if admit != nil {
			if err := admit(prior.Payload); err != nil {
				return 0, err
			}
		}
		data, err := protocol.EncodeJSON(record{
			Version: recordVersion, Kind: kind, Key: key, Generation: next, Epoch: epoch, Payload: payload,
		})
		if err != nil {
			return 0, err
		}
		if w.beforePublish != nil {
			w.beforePublish()
		}
		message := nats.NewMsg(subject(kind, key))
		message.Data = data
		message.Header.Set(EpochHeader, strconv.FormatUint(epoch, 10))
		publishCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		ack, err := w.js.PublishMsg(publishCtx, message,
			jetstream.WithExpectStream(StreamName),
			jetstream.WithExpectLastSequence(lastSequence),
			jetstream.WithExpectLastSequenceForSubject(priorSequence, subject(kind, key)),
			jetstream.WithMsgID(string(kind)+"."+key+"."+strconv.FormatUint(next, 10)),
		)
		cancel()
		if wrongLastSequence(err) {
			// Another append won: a newer term barrier or a concurrent write.
			// The next attempt observes it and fences or re-checks the CAS.
			continue
		}
		if err != nil {
			return 0, fmt.Errorf("publish global %s record: %w", kind, err)
		}
		if ack.Duplicate {
			// The message ID was seen; only an identical stored record is success.
			stored, sequence, readErr := w.read(ctx, kind, key)
			if readErr != nil || stored.Generation != next || !bytes.Equal(stored.Payload, payload) {
				return 0, ErrConflict
			}
			return sequence, nil
		}
		return ack.Sequence, nil
	}
	return 0, ErrConflict
}

internal/globalcontrol/store.go::establi.source:
func (w *Writer) establishTerm(ctx context.Context, epoch uint64) (uint64, error) {
	for range maxAppendAttempts {
		readCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		info, err := w.info(readCtx)
		if err != nil {
			cancel()
			return 0, fmt.Errorf("read global stream sequence: %w", err)
		}
		if err := verifyHome(info.Config, w.replicas); err != nil {
			cancel()
			return 0, err
		}
		current, termSequence, err := readTerm(readCtx, w.stream)
		cancel()
		if err != nil {
			return 0, fmt.Errorf("read global term: %w", err)
		}
		if termSequence > info.State.LastSeq {
			continue
		}
		switch {
		case current == epoch:
			return info.State.LastSeq, nil
		case current > epoch:
			return 0, authority.ErrFenced
		}
		payload, err := protocol.EncodeJSON(term{Epoch: epoch})
		if err != nil {
			return 0, err
		}
		data, err := protocol.EncodeJSON(record{
			Version: recordVersion, Kind: KindTerm, Key: termKey, Generation: epoch, Epoch: epoch, Payload: payload,
		})
		if err != nil {
			return 0, err
		}
		message := nats.NewMsg(subject(KindTerm, termKey))
		message.Data = data
		message.Header.Set(EpochHeader, strconv.FormatUint(epoch, 10))
		publishCtx, publishCancel := context.WithTimeout(ctx, apiTimeout)
		_, err = w.js.PublishMsg(publishCtx, message,
			jetstream.WithExpectStream(StreamName),
			jetstream.WithExpectLastSequenceForSubject(termSequence, subject(KindTerm, termKey)),
		)
		publishCancel()
		if err != nil && !wrongLastSequence(err) {
			return 0, fmt.Errorf("publish global term barrier: %w", err)
		}
		// Re-read: our barrier or a concurrent newer one is now current.
	}
	return 0, ErrConflict
}

internal/globalcontrol/store.go::readTer.source:
func readTerm(ctx context.Context, stream jetstream.Stream) (uint64, uint64, error) {
	message, err := stream.GetLastMsgForSubject(ctx, subject(KindTerm, termKey))
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return 0, 0, nil
	}
	if err != nil {
		return 0, 0, err
	}
	var stored record
	var barrier term
	if err := protocol.DecodeStrict(message.Data, &stored, maxMessageBytes); err != nil ||
		stored.Version != recordVersion || stored.Kind != KindTerm || stored.Key != termKey ||
		stored.Epoch == 0 || stored.Generation != stored.Epoch || !epochHeaderMatches(message.Header, stored.Epoch) ||
		protocol.DecodeStrict(stored.Payload, &barrier, 1024) != nil || barrier.Epoch != stored.Epoch {
		return 0, 0, ErrRecordCorrupt
	}
	return stored.Epoch, message.Sequence, nil
}

internal/globalcontrol/stream.go::Mirror.source:
func MirrorStreamConfig(home, cell string, replicas int) jetstream.StreamConfig {
	return jetstream.StreamConfig{
		Name:         StreamName,
		Description:  "Read-only mirror of the home region's global control stream",
		Retention:    jetstream.LimitsPolicy,
		MaxConsumers: -1, MaxMsgs: -1, MaxBytes: -1, MaxMsgsPerSubject: -1,
		Storage:     jetstream.FileStorage,
		Replicas:    replicas,
		DenyDelete:  true,
		DenyPurge:   true,
		AllowDirect: false,
		Mirror: &jetstream.StreamSource{
			Name:     StreamName,
			External: &jetstream.ExternalStream{APIPrefix: protocol.JSDomainAPIPrefix(home)},
			Consumer: &jetstream.StreamConsumerSource{
				Name:           protocol.GlobalMirrorConsumer(cell),
				DeliverSubject: protocol.InterRegionGlobalDeliverSubject(cell),
			},
		},
		Metadata: map[string]string{"terrascale-contract": contract, "terrascale-role": "mirror", "terrascale-home": home},
	}
}

internal/globalcontrol/stream.go::ensure.source:
func ensureMirrorConsumers(ctx context.Context, stream jetstream.Stream, peers []string, replicas int) error {
	for _, peer := range peers {
		config := MirrorConsumerConfig(peer, replicas)
		createCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		consumer, err := stream.CreatePushConsumer(createCtx, config)
		cancel()
		if errors.Is(err, jetstream.ErrConsumerExists) {
			lookupCtx, lookupCancel := context.WithTimeout(ctx, apiTimeout)
			consumer, err = stream.PushConsumer(lookupCtx, config.Durable)
			lookupCancel()
		}
		if err != nil {
			return fmt.Errorf("create global mirror consumer for %q: %w", peer, err)
		}
		if err := verifyMirrorConsumer(consumer.CachedInfo().Config, peer, replicas); err != nil {
			return err
		}
	}
	return nil
}

internal/globalcontrol/stream.go::openSt.source:
func openStream(ctx context.Context, js jetstream.JetStream, config jetstream.StreamConfig,
	verify func(jetstream.StreamConfig) error,
) (jetstream.Stream, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	createCtx, cancel := context.WithTimeout(ctx, apiTimeout)
	stream, err := js.CreateStream(createCtx, config)
	cancel()
	created := err == nil
	if err != nil {
		if !errors.Is(err, jetstream.ErrStreamNameAlreadyInUse) {
			return nil, fmt.Errorf("create global control stream: %w", err)
		}
		lookupCtx, lookupCancel := context.WithTimeout(ctx, apiTimeout)
		stream, err = js.Stream(lookupCtx, StreamName)
		lookupCancel()
		if err != nil {
			return nil, fmt.Errorf("lookup global control stream: %w", err)
		}
	}
	info, err := inspectStream(ctx, stream, created)
	if err != nil {
		return nil, fmt.Errorf("inspect global control stream: %w", err)
	}
	if err := verify(info.Config); err != nil {
		return nil, err
	}
	// A home stream created before relayed documents bounded messages at
	// 64 KiB; the bound is raised in place.
	if limit := info.Config.MaxMsgSize; limit > 0 && limit < config.MaxMsgSize {
		raised := info.Config
		raised.MaxMsgSize = config.MaxMsgSize
		updateCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		stream, err = js.UpdateStream(updateCtx, raised)
		cancel()
		if err != nil {
			return nil, fmt.Errorf("raise the global control message bound: %w", err)
		}
	}
	return stream, nil
}

internal/globalcontrol/stream.go::inspec.source:
func inspectStream(ctx context.Context, stream jetstream.Stream, created bool) (*jetstream.StreamInfo, error) {
	window, cancel := context.WithTimeout(ctx, createdStreamConvergence)
	defer cancel()
	for {
		infoCtx, infoCancel := context.WithTimeout(window, apiTimeout)
		info, err := stream.Info(infoCtx)
		infoCancel()
		if err == nil || !created || !errors.Is(err, jetstream.ErrStreamNotFound) {
			return info, err
		}
		select {
		case <-window.Done():
			return nil, err
		case <-time.After(100 * time.Millisecond):
		}
	}
}

internal/globalcontrol/stream.go::OpenMi.source:
func OpenMirror(ctx context.Context, js jetstream.JetStream, home, cell string, replicas int) (*Reader, error) {
	if !cellToken.MatchString(home) || !cellToken.MatchString(cell) || home == cell {
		return nil, errors.New("global mirror needs distinct home and regional cells")
	}
	stream, err := openStream(ctx, js, MirrorStreamConfig(home, cell, replicas), func(actual jetstream.StreamConfig) error {
		return verifyMirror(actual, home, cell, replicas)
	})
	if err != nil {
		return nil, err
	}
	return &Reader{stream: stream, js: js, mirror: true}, nil
}

internal/authority/runtime.go::Start.source:
func Start(ctx context.Context, js jetstream.JetStream, config Config) (*Runtime, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	config = config.withDefaults()
	if err := config.validate(); err != nil {
		return nil, err
	}
	if config.ClockCheck != nil && config.ClockCheck() != nil {
		return nil, ErrClockUnhealthy
	}
	logger := config.Logger
	if logger == nil {
		logger = slog.Default()
	}
	stream, err := openControlStream(ctx, js, config.Replicas)
	if err != nil {
		return nil, fmt.Errorf("open authority control log: %w", err)
	}
	readCtx, readCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readStream, err := js.Stream(readCtx, ControlStreamName)
	readCancel()
	if err != nil {
		return nil, fmt.Errorf("open authority read handle: %w", err)
	}
	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readInfo, err := readStream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return nil, fmt.Errorf("inspect authority read handle: %w", err)
	}
	if err := verifyControlStreamConfig(readInfo.Config, config.Replicas); err != nil {
		return nil, fmt.Errorf("validate authority read handle: %w", err)
	}
	loopCtx, cancel := context.WithCancel(ctx)
	runtime := &Runtime{
		js:          js,
		publisher:   js,
		stream:      stream,
		readStream:  readStream,
		config:      config,
		leaseSub:    fmt.Sprintf("%s.%s.lease", controlSubjectRoot, config.Scope),
		ownerID:     entityid.New(),
		logger:      logger,
		diagnostics: authorityDiagnosticQueue,
		diagTimes:   make(map[string]time.Time),
		cancel:      cancel,
		done:        make(chan struct{}),
	}
	runtime.publishSnapshot(Snapshot{Scope: config.Scope, DeploymentID: config.DeploymentID, CandidateID: config.CandidateID, OwnerID: runtime.ownerID, Reason: "not-observed"})
	runtime.logSnapshotTransition()
	var observeErr error
	for attempt := range startupReconcileAttempts {
		observeErr = runtime.reconcileWithRetry(loopCtx)
		runtime.logSnapshotTransition()
		if observeErr != nil && loopCtx.Err() != nil {
			observeErr = loopCtx.Err()
			break
		}
		if observeErr == nil || !retryableStartupReconcileError(loopCtx, observeErr) || attempt+1 == startupReconcileAttempts {
			break
		}
		timer := time.NewTimer(startupReconcileDelay(attempt, observeErr))
		select {
		case <-loopCtx.Done():
			observeErr = loopCtx.Err()
			timer.Stop()
		case <-timer.C:
		}
	}
	if observeErr != nil {
		cancel()
		close(runtime.done)
		return nil, fmt.Errorf("observe authority lease: %w", observeErr)
	}
	go runtime.run(loopCtx)
	return runtime, nil
}

internal/authority/runtime.go::reconcile.source:
func (r *Runtime) reconcile(ctx context.Context) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	info, err := r.stream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return stageFailure("stream_info", err)
	}
	if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
		return stageFailure("stream_config", err)
	}
	entryCtx, entryCancel := context.WithTimeout(ctx, authorityAPITimeout)
	entry, err := r.stream.GetLastMsgForSubject(entryCtx, r.leaseSub)
	entryCancel()
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return r.acquire(ctx, info.State.LastSeq, 0, 1)
	}
	if err != nil {
		return stageFailure("lease_msg_get", err)
	}
	if entry.Sequence > info.State.LastSeq {
		return stageFailure("lease_sequence_check", ErrConflict)
	}
	lease, err := decodeLease(entry.Data)
	if err != nil || lease.Scope != r.config.Scope || lease.Epoch == 0 {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Revision: entry.Sequence, ObservedAt: time.Now(), Reason: "lease-corrupt"})
		return nil
	}
	if lease.DeploymentID != r.config.DeploymentID {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID,
			CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Epoch: lease.Epoch,
			Revision: entry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
		return nil
	}
	expiresAt := entry.Time.Add(time.Duration(lease.LeaseDuration))
	now := time.Now()
	current := r.Current()
	if lease.IdentityResetSHA256 != "" {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID,
			CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Epoch: lease.Epoch,
			Revision: entry.Sequence, ObservedAt: now, Reason: "identity-reset-pending"})
		return nil
	}
	if !lease.Released && now.Before(expiresAt) {
		if lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID {
			r.publishSnapshot(Snapshot{
				Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Ready: true,
				Epoch: lease.Epoch, Revision: entry.Sequence, ExpiresAt: expiresAt,
				ObservedAt: now, Reason: "follower",
			})
			return nil
		}
		if current.Epoch != lease.Epoch || !current.Leader {
			return r.appendLease(ctx, info.State.LastSeq, entry.Sequence, lease.Epoch, false)
		}
		return r.appendLease(ctx, info.State.LastSeq, entry.Sequence, lease.Epoch, false)
	}
	if lease.CandidateID == r.config.CandidateID && lease.OwnerID == r.ownerID && current.Leader && current.Epoch == lease.Epoch {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Revision: entry.Sequence, ObservedAt: now, Reason: "lease-expired"})
	}
	return r.acquire(ctx, info.State.LastSeq, entry.Sequence, lease.Epoch+1)
}

internal/authority/runtime.go::acquire.source:
func (r *Runtime) acquire(ctx context.Context, lastSequence, leaseSequence, epoch uint64) error {
	return r.appendLease(ctx, lastSequence, leaseSequence, epoch, false)
}

internal/authority/runtime.go::appendLea.source:
func (r *Runtime) appendLease(ctx context.Context, lastSequence, leaseSequence, epoch uint64, released bool) error {
	if epoch == 0 {
		return ErrFenced
	}
	if !released && r.checkClock() != nil {
		return ErrClockUnhealthy
	}
	lease := leaseRecord{
		Version: 1, Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID,
		Epoch: epoch, LeaseDuration: int64(r.config.LeaseDuration), TransitionID: entityid.New(), Released: released,
	}
	data, err := jsonMarshal(lease)
	if err != nil {
		return stageFailure("lease_encode", err)
	}
	msg := controlMessage(r.leaseSub, "lease", lease.TransitionID, data)
	publishCtx, publishCancel := context.WithTimeout(ctx, authorityAPITimeout)
	ack, err := r.publisher.PublishMsg(publishCtx, msg,
		jetstream.WithExpectLastSequence(lastSequence),
		jetstream.WithExpectLastSequenceForSubject(leaseSequence, r.leaseSub),
	)
	publishCancel()
	if err != nil {
		if isSequenceConflict(err) {
			return stageFailure("lease_publish", ErrConflict)
		}
		return stageFailure("lease_publish", r.resolveLeaseAppend(ctx, lease, err))
	}
	confirmCtx, confirmCancel := context.WithTimeout(ctx, authorityAPITimeout)
	stored, err := r.stream.GetLastMsgForSubject(confirmCtx, r.leaseSub)
	confirmCancel()
	if err != nil {
		return stageFailure("lease_confirm_get", r.resolveLeaseAppend(ctx, lease, err))
	}
	if stored.Sequence != ack.Sequence {
		return stageFailure("lease_confirm_sequence", ErrConflict)
	}
	confirmed, err := decodeLease(stored.Data)
	if err != nil || confirmed.Scope != r.config.Scope || confirmed.DeploymentID != r.config.DeploymentID || confirmed.CandidateID != r.config.CandidateID || confirmed.OwnerID != r.ownerID || confirmed.Epoch != epoch || confirmed.TransitionID != lease.TransitionID || confirmed.Released != released {
		return stageFailure("lease_confirm_record", ErrFenced)
	}
	if released {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Epoch: epoch, Revision: ack.Sequence, ObservedAt: time.Now(), Reason: "released"})
		return nil
	}
	now := time.Now()
	expiresAt := stored.Time.Add(time.Duration(confirmed.LeaseDuration))
	if !now.Before(expiresAt) {
		return stageFailure("lease_confirm_expiry", ErrFenced)
	}
	r.publishSnapshot(Snapshot{
		Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Leader: true, Ready: true,
		Epoch: epoch, Revision: ack.Sequence, ExpiresAt: expiresAt, ObservedAt: now, Reason: "leader",
	})
	return nil
}

